preConditionHook:
// HighLowBarCount's counter read as a STANDING THRESHOLD instead of an
// equality: 'a pullback, like all trends, will commonly have at least two
// legs', so a with-trend entry is favoured only once the count has reached
// two. HighLowBarCount fires on ONE bar (the signal bar, count == countTarget
// with the advance flag); this stays true for the rest of the pullback, so as
// a context filter ANDed into a pane the two select different bars.
//
// THE COUNTER IS THE SETTLED ONE (Ranges ch17, R17-01) and is INLINED here
// rather than referenced -- rules in this corpus never reference each other.
// See HighLowBarCount for the full commentary; in short, a higher-high bar
// advances the count only after a new low has formed since the last counted
// bar, the count resets on a fresh resetLookback-bar high measured one bar
// ago, and it saturates at 4. The advance flag is not needed here, so it is
// not carried. The reset window is EL's Highest(high, resetLookback)[1] --
// the N bars ENDING ONE BAR AGO -- and Extremes() is EasyLanguage source, so
// the scan carries the relational tolerance through el_gt / el_lt.
//
// MIRRORED, not identical: the merged slice recorded sides = same, but the
// counter is inherently directional -- the long side counts the higher-high
// bars of a bull-flag pullback and the short side the lower-low bars of a
// bear-flag pullback -- so an identical short condition would have a short
// placement reading the bull flag's legs.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
if (el_gt(close[0], priorHigh)) {
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
    }
}
if (el_lt(close[0], priorLow)) {
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
    }
}
